<?php
require_once __DIR__.'/../includes/auth.php';requireAdmin();if($_SERVER['REQUEST_METHOD']==='POST'){verifyCsrf();$id=(int)($_POST['id']??0);$pdo->prepare('UPDATE admin_notifications SET is_read=1 WHERE id=?')->execute([$id]);redirect('notifications.php');}$rows=$pdo->query('SELECT * FROM admin_notifications ORDER BY created_at DESC LIMIT 100')->fetchAll();$pageTitle='Admin notifications';require __DIR__.'/../includes/header.php';?>
<section class="page-heading"><div><p class="eyebrow">ADMIN UPDATES</p><h1>Notifications</h1></div></section><section class="panel"><?php foreach($rows as $n):?><article class="notification-row"><div><strong><?=e($n['title'])?></strong><p><?=e($n['message'])?></p><small><?=e($n['created_at'])?></small></div><?php if(!$n['is_read']):?><form method="post"><input type="hidden" name="csrf_token" value="<?=e(csrfToken())?>"><input type="hidden" name="id" value="<?=(int)$n['id']?>"><button class="button light btn-small">Mark read</button></form><?php endif;?></article><?php endforeach;?></section><?php require __DIR__.'/../includes/footer.php';?>
